package com.personal.assistant.module.lifemanagement.service;import com.personal.assistant.common.exception.BusinessException;import com.personal.assistant.module.reminder.service.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import org.springframework.jdbc.core.JdbcTemplate;import java.util.Map;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class)class LifeManagementServiceTest{@Mock JdbcTemplate jdbc;@Mock ReminderService reminders;@Mock SecretCryptoService crypto;@Test void sensitiveAssetRequiresSecondConfirmation(){when(jdbc.queryForMap(anyString(),eq(5L),eq(3L))).thenReturn(Map.of("sensitive",true,"encrypted_details","cipher"));LifeManagementService service=new LifeManagementService(jdbc,reminders,crypto);assertThrows(BusinessException.class,()->service.revealAsset(3L,5L,"NO"));when(crypto.decrypt("cipher")).thenReturn("保单号 123");assertEquals("保单号 123",service.revealAsset(3L,5L,"CONFIRM"));}}
